<?php
declare(strict_types=1);session_name('LBFP_OWNER');session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Strict','path'=>'/']);session_start();require_once __DIR__.'/../shared/bootstrap.php';method('POST');same_origin();$d=body();$action=clean($d['action']??'',40);if($action==='logout'){if(!empty($_SESSION['owner_id'])&&hash_equals((string)($_SESSION['csrf']??''),(string)($d['csrf']??''))){$_SESSION=[];session_destroy();}header('Location: ../../owner.php');exit;}if(empty($_SESSION['owner_id']))reply(401,['ok'=>false,'message'=>'Please sign in again.']);if(!hash_equals((string)($_SESSION['csrf']??''),(string)($d['csrf']??'')))reply(403,['ok'=>false,'message'=>'Security token expired. Refresh the page.']);$p=db();
if($action==='dashboard'){ $q=$p->query('SELECT o.id,o.order_number,o.status,o.fulfillment,o.payment_method,o.address,o.customer_latitude,o.customer_longitude,o.delivery_boy_name,o.delivery_boy_phone,o.delivery_notes,o.preferences,o.subtotal,o.total,o.created_at,o.updated_at,c.name AS customer_name,c.phone,c.email FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.id DESC LIMIT 200');$orders=$q->fetchAll();$items=$p->query('SELECT order_id,item_name,unit_price,quantity,line_total FROM order_items ORDER BY order_id DESC')->fetchAll();$by=[];foreach($items as $it)$by[(int)$it['order_id']][]=$it;foreach($orders as &$o)$o['items']=$by[(int)$o['id']]??[];unset($o);$menu=$p->query('SELECT id,name,category,price,is_available FROM menu_items ORDER BY sort_order,name')->fetchAll();reply(200,['ok'=>true,'orders'=>$orders,'menu'=>$menu]);}
if($action==='update_status'){$id=filter_var($d['order_id']??null,FILTER_VALIDATE_INT);$status=clean($d['status']??'',30);$allowed=['Received','Confirmed','Preparing','Ready','Out for delivery','Completed','Cancelled'];if(!$id||!in_array($status,$allowed,true))reply(422,['ok'=>false,'message'=>'Invalid order or status.']);$q=$p->prepare('UPDATE orders SET status=?,updated_at=UTC_TIMESTAMP() WHERE id=?');$q->execute([$status,$id]);reply(200,['ok'=>true]);}
if($action==='assign_delivery'){$id=filter_var($d['order_id']??null,FILTER_VALIDATE_INT);$name=clean($d['name']??'',100);$phone=phone($d['phone']??'');$notes=clean($d['notes']??'',500);if(!$id||$name===''||strlen(preg_replace('/\D/','',$phone)??'')<10)reply(422,['ok'=>false,'message'=>'Enter the delivery person name and a valid mobile number.']);$q=$p->prepare("UPDATE orders SET delivery_boy_name=?,delivery_boy_phone=?,delivery_notes=?,status=IF(status IN ('Received','Confirmed','Preparing','Ready'),'Out for delivery',status),updated_at=UTC_TIMESTAMP() WHERE id=? AND fulfillment='Delivery'");$q->execute([$name,$phone,$notes,$id]);if(!$q->rowCount())reply(422,['ok'=>false,'message'=>'Delivery order not found, or no changes were made.']);reply(200,['ok'=>true]);}
if($action==='toggle_menu'){$id=filter_var($d['menu_item_id']??null,FILTER_VALIDATE_INT);$available=filter_var($d['available']??null,FILTER_VALIDATE_INT);if(!$id||!in_array($available,[0,1],true))reply(422,['ok'=>false,'message'=>'Invalid menu update.']);$q=$p->prepare('UPDATE menu_items SET is_available=? WHERE id=?');$q->execute([$available,$id]);reply(200,['ok'=>true]);}
reply(400,['ok'=>false,'message'=>'Unknown action.']);
